t.tenant_id = #{visibility.tenantId} AND NOT t.deleted AND t.opened
AND ((t.permission_code IS NULL AND EXISTS (SELECT 1 FROM todo_membership m
WHERE m.tenant_id = #{visibility.tenantId} AND m.todo_id = t.id AND m.membership_id = #{visibility.membershipId}))

    OR t.permission_code IN
    #{permission}

)

    AND (t.app_code IS NULL

        OR t.app_code IN
        #{app}

    )

mapper.select:
SELECT t.id, t.service, t.business_key, t.title, t.body, t.app_code, t.route, t.occurred_at, t.occurred_at_nanos
FROM todo t WHERE

ORDER BY t.occurred_at DESC, t.occurred_at_nanos DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}
